/* From Uiverse.io by nikk7007 - Tags: button */
.__UIV_SCOPE__ .btn {
 --color: #00A97F;
 --color2: rgb(10, 25, 30);
 padding: 0.8em 1.75em;
 background-color: transparent;
 border-radius: 6px;
 border: .3px solid var(--color);
 transition: .5s;
 position: relative;
 overflow: hidden;
 cursor: pointer;
 z-index: 1;
 font-weight: 300;
 font-size: 17px;
 font-family: 'Roboto', 'Segoe UI', sans-serif;
 text-transform: uppercase;
 color: var(--color);
}

.__UIV_SCOPE__ .btn::after, .__UIV_SCOPE__ .btn::before {
 content: '';
 display: block;
 height: 100%;
 width: 100%;
 transform: skew(90deg) translate(-50%, -50%);
 position: absolute;
 inset: 50%;
 left: 25%;
 z-index: -1;
 transition: .5s ease-out;
 background-color: var(--color);
}

.__UIV_SCOPE__ .btn::before {
 top: -50%;
 left: -25%;
 transform: skew(90deg) rotate(180deg) translate(-50%, -50%);
}

.__UIV_SCOPE__ .btn:hover::before {
 transform: skew(45deg) rotate(180deg) translate(-50%, -50%);
}

.__UIV_SCOPE__ .btn:hover::after {
 transform: skew(45deg) translate(-50%, -50%);
}

.__UIV_SCOPE__ .btn:hover {
 color: var(--color2);
}

.__UIV_SCOPE__ .btn:active {
 filter: brightness(.7);
 transform: scale(.98);
}
